// Package-local (NOT vendored) additions to the authz package.
//
// reader.go and vocab.go are vendored verbatim from entiredb core/authz and
// carry a source-commit header; a re-sync overwrites THOSE. This file is local
// to activity and must NOT be overwritten on re-sync — it deliberately avoids
// the upstream filename (core/authz/subject.go) so a file-by-name re-sync can't
// silently clobber it.
package authz

// AccountSubject builds the SpiceDB subject for an account principal — the
// identity an authz question is asked about.
//
// entiredb's core/authz/subject.go takes a model.AccountID
// (entire.io/core/model, unavailable here), so activity supplies its own helper
// over the account id string. That id MUST come from the verified caller
// Identity, never from request input — the read-only key can query ANY account.
func AccountSubject(id string) Subject {
	return Subject{Type: "account", ID: id}
}

// AutomationSubject builds the SpiceDB subject for an automation principal
// (ADR 20260728-automation-principal, COR-1109) — an automation runs as its
// own subject type, never nested under "account", so this is a distinct
// constructor rather than a prefixed account id. id is the automation row's
// SpiceDB object id (aut_<ulid>), which MUST come from the verified caller
// Identity (Identity.AuthzSubject), never from request input.
func AutomationSubject(id string) Subject {
	return Subject{Type: "automation", ID: id}
}

// AnonSubject returns a synthetic SpiceDB subject used to probe whether a repo
// has the public_viewer wildcard set. SpiceDB's account:* wildcard matches ANY
// account id, so this fixed sentinel works for the probe — it never identifies
// a real caller and must not be used for anything beyond the public-visibility
// check.
func AnonSubject() Subject {
	return Subject{Type: "account", ID: "__anon__"}
}

